            self.data@.len = (self.data@.len - 1) as nat;
            assert forall |i: nat| self.valid_node(i, #[trigger] self.next_ptr(i))
            by {
                assert(old(self).valid_node(i, old(self).next_ptr(i)));
                if i > 0 {
                    let j = (i - 1) as nat;
                    assert(old(self).valid_node(j, old(self).next_ptr(j)));
